files.content:
* {
  box-sizing: border-box;
}

body {
  min-width: 850px;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  background-color: #000;
}

.container {
  display: grid;
  grid-template-columns: 190px 200px 270px;
  grid-template-rows: 150px 150px 100px;
  gap: 10px;
}

.container p {
  margin: 0;
  padding: 10px;
  font-size: 40px;
}

.container p:first-of-type {
  background-color: white;
}

.container p:nth-of-type(2) {
  background-color: #feafe8;
}

.container p:nth-of-type(3) {
  background-color: #80d994;
}

.container p:nth-of-type(4) {
  background-color: #feafe8;
}

.container p:nth-of-type(5) {
  background-color: #80d994;
}

.container p:nth-of-type(6) {
  background-color: white;
}

.container p:nth-of-type(7) {
  background-color: white;
}

.container p:nth-of-type(8) {
  background-color: #feafe8;
}

.container p:nth-of-type(9) {
  background-color: #80d994;
}
